echo '== vet'; E=0; go vet -overlay $P/overlay.json ./supervisor || E=1
echo '== gofmt'; F=$(gofmt -l supervisor/guard.go 2>&1) || true; [ -z "$F" ] || { echo "gofmt -l lists: $F"; gofmt -d supervisor/guard.go 2>&1 | head -60; E=1; }
echo '== guard'; node $P/guard.mjs src supervisor/guard.go
